script:
frappe.ui.form.on("Therapy Package Enrollment", {
    refresh: function(frm) {
        frm.set_query("package", function() {
            return {
                filters: {
                    item_group: "Therapy Packages"
                }
            };
        });
    }
});

frappe.ui.form.on('Therapy Plan Template', {
	discount(frm) {
		var discount=frm.doc.discount;
		var total_amount=frm.doc.total_amount
		var total_amount2=total_amount-discount
		frm.set_value('total_amount',total_amount2)
	}
})

frappe.ui.form.on('Therapy Plan', {
    // When therapy plan template is selected
    therapy_plan_template: function(frm) {
        frappe.after_ajax(() => {
            if (frm.doc.start_date) {
                (frm.doc.therapy_plan_details || []).forEach(row => {
                    row.date = frm.doc.start_date;
                    row.day = moment(frm.doc.start_date).format('dddd'); 
                });
                frm.refresh_field('therapy_plan_details');
            }
        });
    },

    // When new row is added
    therapy_plan_details_add: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        if (frm.doc.start_date) {
            row.date = frm.doc.start_date;
            row.day = moment(frm.doc.start_date).format('dddd'); 
            row.status = 'Remaining'; // Default status
            frm.refresh_field('therapy_plan_details');
        }
    },

    patient: function(frm) {
        if (frm.doc.start_date) {
            (frm.doc.therapy_plan_details || []).forEach(row => {
                row.date = frm.doc.start_date;
                row.day = moment(frm.doc.start_date).format('dddd'); 
            });
            frm.refresh_field('therapy_plan_details');
        }
    },
    
    start_date: function(frm) {
        if (frm.doc.start_date) {
            (frm.doc.therapy_plan_details || []).forEach(row => {
                row.date = frm.doc.start_date;
                row.day = moment(frm.doc.start_date).format('dddd'); 
            });
            frm.refresh_field('therapy_plan_details');
        }
    }
});

// --- CHILD TABLE UI EVENTS: Status & Read-Only Handling ---
frappe.ui.form.on('Therapy Plan Detail', {
    form_render: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        // Agar status Completed hai, toh button ko Grid Form me Read-Only (Disable) kar do
        let is_completed = (row.status === 'Completed');
        frm.fields_dict['therapy_plan_details'].grid.update_docfield_property(
            'slot_assign', 'read_only', is_completed ? 1 : 0
        );
    },
    
    status: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        let is_completed = (row.status === 'Completed');
        frm.fields_dict['therapy_plan_details'].grid.update_docfield_property(
            'slot_assign', 'read_only', is_completed ? 1 : 0
        );
        frm.refresh_field('therapy_plan_details');
    }
});

// --- MAIN SLOT ASSIGN BUTTON ACTION ---
frappe.ui.form.on('Therapy Plan Detail', 'slot_assign', function(frm, cdt, cdn) { 
    if (frm.is_new()) {
        frappe.msgprint({
            'title': __('Form Not Saved'),
            'message': __('Please save the Therapy Plan form first before assigning slots.'),
            'indicator': 'red'
        });
        return;
    }

    const row = locals[cdt][cdn];
    
    // --- STRICT GUARD: Check if status is already Completed ---
    if (row.status === 'Completed') {
        frappe.msgprint({
            title: __('Action Blocked (Completed)'),
            message: __('Slots for this therapy service have already been assigned and marked as <b>Completed</b>. You cannot assign slots again unless the status is changed back to Remaining.'),
            indicator: 'orange'
        });
        return;
    }
    
    // --- VALIDATIONS ---
    if (!frm.doc.start_date) { frappe.msgprint('Please set Start Date on the Therapy Plan before assigning slots.'); return; }
    if (!frm.doc.end_date) { frappe.msgprint('Please set End Date on the Therapy Plan before assigning slots.'); return; } 
    if (!row.therapy_type) { frappe.msgprint('Please set Therapy Type in the current row before assigning slots.'); return; }
    if (!row.healthcare_practitioner) { frappe.msgprint('Please set Healthcare Practitioner in the current row before assigning slots.'); return; }
    if (!row.frequency) { frappe.msgprint('Please set Frequency in the current row before assigning slots.'); return; }

    function addDays(date, n) { return frappe.datetime.add_days(date, n); }
    function dayName(date) {
        const d = new Date(date + 'T00:00:00');
        return d.toLocaleDateString(undefined, { weekday: 'long' });
    }
    function isWeekend(day) { return day.toLowerCase() === 'saturday' || day.toLowerCase() === 'sunday'; }

    const freq = (row.frequency || '').toLowerCase();
    let step = 1;
    if (freq === 'daily') step = 1;
    else if (freq === 'alternate days' || freq === 'alternate_days' || freq === 'alternate-days') step = 2;
    else if (freq === 'weekly') step = 7;

    const sessions = parseInt(row.no_of_sessions || 0, 10);
    if (!sessions || sessions <= 0) {
        frappe.msgprint('Please enter a valid No of Sessions in the current row.');
        return;
    }

    const start_date = frm.doc.start_date;
    const end_date = frm.doc.end_date;

    let practitioner_name = row.practitioner_name;
    if (!practitioner_name) {
        frappe.call({
            method: 'frappe.client.get_value',
            args: { doctype: 'Healthcare Practitioner', fieldname: 'practitioner_name', filters: { name: row.healthcare_practitioner } },
            callback: function(r) { if (r.message && r.message.practitioner_name) practitioner_name = r.message.practitioner_name; }
        });
    }

    const schedule = [];
    let current = start_date;
    let sessions_added = 0;
    
    while (sessions_added < sessions) {
        if (current > end_date) {
            frappe.msgprint({title: 'Date Limit Reached', message: `Cannot generate all ${sessions} sessions. Auto-generation reached the End Date (${end_date}). Generated ${sessions_added} sessions.`, indicator: 'orange'});
            break; 
        }

        const day = dayName(current);
        if (!isWeekend(day)) {
            schedule.push({
                date: current,
                day: day,
                healthcare_practitioner: row.healthcare_practitioner || '',
                practitioner_name: practitioner_name || '',
                token_no: '', 
                therapy_type: row.therapy_type || '',
                no_of_sessions: 1
            });
            sessions_added++;
        }

        // --- SMART ALTERNATE DAYS & WEEKEND JUMP LOGIC ---
        if (step === 2) {
            // Agar aaj Thursday hai, +2 Saturday banta tha -> Jump +4 days to Monday!
            if (day.toLowerCase() === 'thursday') {
                current = addDays(current, 4);
            } 
            // Agar aaj Friday hai, +2 Sunday banta tha -> Jump +3 days to Monday!
            else if (day.toLowerCase() === 'friday') {
                current = addDays(current, 3);
            } 
            // Normal working day (e.g., Mon -> Wed -> Fri)
            else {
                current = addDays(current, 2);
            }
        } else if (step === 1) {
            // Daily frequency weekend jump logic
            let next_day = addDays(current, 1);
            if (dayName(next_day).toLowerCase() === 'saturday') {
                current = addDays(current, 3); // Skip Sat & Sun -> Monday
            } else if (dayName(next_day).toLowerCase() === 'sunday') {
                current = addDays(current, 2); // Skip Sun -> Monday
            } else {
                current = addDays(current, 1);
            }
        } else {
            current = addDays(current, step);
        }
    }

    // STRICT TOKEN TO TIME MAPPING
    const TOKEN_TIME_MAP = {
        1: { from: '09:30:00', to: '10:00:00' },
        2: { from: '10:00:00', to: '10:30:00' },
        3: { from: '10:30:00', to: '11:00:00' },
        4: { from: '11:00:00', to: '11:30:00' },
        5: { from: '11:30:00', to: '12:00:00' },
        6: { from: '12:00:00', to: '12:30:00' },
        7: { from: '12:30:00', to: '13:00:00' },
        8: { from: '14:00:00', to: '14:30:00' },
        9: { from: '14:30:00', to: '15:00:00' },
        10: { from: '15:00:00', to: '15:30:00' },
        11: { from: '15:30:00', to: '16:00:00' },
        12: { from: '16:00:00', to: '16:30:00' },
        13: { from: '16:30:00', to: '17:00:00' }
    };

    frappe.dom.freeze(__('Fetching booked tokens and assigning available slots...'));
    
    async function prepareScheduleAndShow() {
        try {
            let dates_to_check = schedule.map(s => s.date);
            
            let booked_slots_response = await frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Therapy Automation',
                    filters: [
                        ['date', 'in', dates_to_check],
                        ['booked', '=', 1]
                    ],
                    or_filters: [
                        ['healthcare_practitioner', '=', row.healthcare_practitioner],
                        ['patient', '=', frm.doc.patient] // Patient overlap fix applied here
                    ],
                    fields: ['date', 'token_no'],
                    limit_page_length: 5000 
                }
            }).then(r => r.message || []);

            let local_booked_tokens = {}; 
            dates_to_check.forEach(d => local_booked_tokens[d] = []);
            
            booked_slots_response.forEach(b => {
                let t_no = parseInt(b.token_no);
                if (!isNaN(t_no)) {
                    local_booked_tokens[b.date].push(t_no);
                }
            });

            for (let i = 0; i < schedule.length; i++) {
                let sched = schedule[i];
                let date_key = sched.date;
                
                let assigned_token = null;
                for (let t = 1; t <= 13; t++) {
                    if (!local_booked_tokens[date_key].includes(t)) {
                        assigned_token = t;
                        local_booked_tokens[date_key].push(t); 
                        break;
                    }
                }
                
                if (assigned_token) {
                    sched.token_no = assigned_token;
                    sched.from_time = TOKEN_TIME_MAP[assigned_token].from;
                    sched.to_time = TOKEN_TIME_MAP[assigned_token].to;
                    sched._status = 'success';
                } else {
                    sched.token_no = '';
                    sched.from_time = '';
                    sched.to_time = '';
                    sched._note = 'Max 13 Sessions Reached. No token available.';
                    sched._status = 'danger';
                }
            }
            
            frappe.dom.unfreeze();
            showEnhancedDialog(schedule, TOKEN_TIME_MAP);
        } catch (error) {
            frappe.dom.unfreeze();
            frappe.msgprint(__('Error fetching data: {0}', [error]));
        }
    }
    
    prepareScheduleAndShow();

    function showEnhancedDialog(schedule_data, tokenMap) {
        function checkForDuplicates(scheduleData) {
            const seenCombinations = new Map();
            const duplicates = [];
            scheduleData.forEach((item, index) => {
                if (item.date && item.token_no) {
                    const combinationKey = `${item.date}-${item.token_no}`;
                    if (seenCombinations.has(combinationKey)) {
                        const originalIndex = seenCombinations.get(combinationKey);
                        duplicates.push({
                            firstRow: originalIndex + 1,
                            secondRow: index + 1,
                            date: item.date,
                            token: item.token_no
                        });
                    } else {
                        seenCombinations.set(combinationKey, index);
                    }
                }
            });
            return duplicates;
        }

        const table_html = function(rows) {
            let html = `
                <div class="schedule-dialog-container">
                    <div class="schedule-summary-card mb-3">
                        <div class="row">
                            <div class="col-md-3"><strong>Therapy Type:</strong><br><span class="text-primary">${row.therapy_type || 'N/A'}</span></div>
                            <div class="col-md-3"><strong>Practitioner:</strong><br><span class="text-primary">${practitioner_name || row.healthcare_practitioner || 'N/A'}</span></div>
                            <div class="col-md-3"><strong>Frequency:</strong><br><span class="text-primary">${row.frequency || 'N/A'}</span></div>
                            <div class="col-md-3"><strong>Sessions:</strong><br><span class="text-primary">${rows.length}</span></div>
                        </div>
                    </div>

                    <div class="alert alert-info mb-3">
                        <i class="fa fa-info-circle mr-2"></i>
                        Date and Token Number are Editable!
                        <strong class="d-block mt-1">Date must be between ${frm.doc.start_date} and ${frm.doc.end_date}.</strong>
                    </div>

                    <div class="schedule-table-container" style="max-height: 400px; overflow: auto; border: 1px solid #e6e6e6; border-radius: 8px;">
                        <table class="table table-hover table-sm mb-0" style="margin: 0;">
                            <thead style="position: sticky; top: 0; background: #f9fafb; z-index: 1;">
                                <tr>
                                    <th style="min-width: 140px;" class="text-center">Date (Editable)</th>
                                    <th style="min-width: 90px;" class="text-center">Day</th>
                                    <th style="min-width: 100px;" class="text-center">Token No</th>
                                    <th style="min-width: 100px;" class="text-center">From Time</th>
                                    <th style="min-width: 100px;" class="text-center">To Time</th>
                                    <th style="min-width: 80px;" class="text-center">Status</th>
                                </tr>
                            </thead>
                            <tbody>`;
            rows.forEach(function(r, idx){
                const isWeekendDay = isWeekend(r.day);
                const statusClass = isWeekendDay ? 'weekend' : r._status || 'default';
                const statusText = isWeekendDay ? 'Weekend' : (r._note ? 'Check' : 'Available');
                const statusIcon = isWeekendDay ? '❌' : (r._note ? '⚠️' : '✅');
                
                html += `
                                <tr class="schedule-row ${isWeekendDay ? 'weekend-row' : ''}" data-idx="${idx}">
                                    <td class="text-center">
                                        <input type="date" class="form-control input-sm sched-date text-center" 
                                               value="${r.date || ''}" 
                                               min="${frm.doc.start_date}" max="${frm.doc.end_date}" 
                                               style="border: 2px solid #667eea; font-weight: bold; cursor: pointer;" />
                                    </td>
                                    <td class="text-center">
                                        <span class="day-badge ${r.day.toLowerCase()}">${r.day}</span>
                                    </td>
                                    <td class="text-center">
                                        <input type="number" min="1" max="13" class="form-control input-sm sched-token text-center ${r._note ? 'no-token' : 'has-token'}" 
                                               value="${r.token_no || ''}" 
                                               style="border: 2px solid ${r._note ? '#ffa726' : '#667eea'}; font-weight: bold;" 
                                               placeholder="1-13" />
                                    </td>
                                    <td class="text-center">
                                        <input type="time" class="form-control input-sm sched-from-time text-center readonly-field" 
                                               value="${(r.from_time || '').substring(0, 5)}" readonly />
                                    </td>
                                    <td class="text-center">
                                        <input type="time" class="form-control input-sm sched-to-time text-center readonly-field" 
                                               value="${(r.to_time || '').substring(0, 5)}" readonly />
                                    </td>
                                    <td class="text-center">
                                        <span class="status-badge ${statusClass}" title="${r._note || ''}">
                                            ${statusIcon} ${statusText}
                                        </span>
                                    </td>
                                </tr>`;
            });
            
            html += `
                            </tbody>
                        </table>
                    </div>
                </div>
                
                <style>
                    .schedule-summary-card { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px;}
                    .schedule-summary-card strong { color: rgba(255,255,255,0.9); font-size: 12px; }
                    .schedule-summary-card .text-primary { color: white !important; font-weight: 600; }
                    .readonly-field { background-color: #f1f3f5 !important; cursor: not-allowed; opacity: 0.8; pointer-events: none; }
                    .weekend-row { background-color: #fff5f5; }
                    .day-badge { display: inline-block; padding: 4px 8px; border-radius: 12px; font-size: 11px; font-weight: 600; text-transform: uppercase;}
                    .status-badge { display: inline-block; padding: 4px 8px; border-radius: 12px; font-size: 11px; font-weight: 600;}
                    .status-badge.success { background: #e8f5e8; color: #2e7d32; }
                    .status-badge.warning { background: #fff3e0; color: #ef6c00; }
                    .status-badge.danger { background: #ffebee; color: #c62828; }
                    .duplicate-row { background-color: #ffecb3 !important; }
                </style>
            `;
            return html;
        }

        const d = new frappe.ui.Dialog({
            title: `
                <div class="dialog-title-content">
                    <i class="fa fa-calendar-check-o text-primary mr-2"></i>Smart Therapy Scheduler
                </div>
            `,
            size: 'large',
            fields: [{ fieldname: 'schedule_table', fieldtype: 'HTML', options: table_html(schedule_data) }],
            primary_action_label: '<i class="fa fa-check mr-2"></i>Confirm & Save',
            primary_action: function() {
                const $rows = d.$wrapper.find('tbody tr');
                const therapy_automation_data = [];
                const updated_schedule = [];
                const scheduleDataForDup = [];
                let hasError = false;
                
                $rows.each(function() {
                    const $row = $(this);
                    const row_index = $row.data('idx');
                    const date = $row.find('.sched-date').val();
                    const day = $row.find('.day-badge').text();
                    const token_no = $row.find('.sched-token').val();
                    const from_time = $row.find('.sched-from-time').val();
                    const to_time = $row.find('.sched-to-time').val();
                    
                    if ($row.hasClass('weekend-row') || isWeekend(day)) {
                        frappe.msgprint({title: 'Weekend Error', message: `Row ${row_index + 1}: Cannot assign token on weekend!`, indicator: 'red'});
                        hasError = true;
                        return false; 
                    }
                    
                    if (!date || !token_no || !from_time) {
                        frappe.msgprint({title: 'Action Blocked', message: `Row ${row_index + 1}: Date or Token is missing. If slots are full for this date, please select another valid date.`, indicator: 'red'});
                        hasError = true;
                        return false;
                    }

                    scheduleDataForDup.push({ row: row_index + 1, date: date, token_no: token_no });

                    updated_schedule.push({
                        date: date, day: day,
                        healthcare_practitioner: row.healthcare_practitioner,
                        token_no: token_no, therapy_type: row.therapy_type, no_of_sessions: 1
                    });

                    therapy_automation_data.push({
                        therapy_plan: frm.doc.name,
                        therapy_plan_detail: row.name,
                        patient: frm.doc.patient, 
                        therapy_type: row.therapy_type,
                        healthcare_practitioner: row.healthcare_practitioner,
                        practitioner_name: row.practitioner_name || practitioner_name,
                        date: date, day: day, token_no: token_no,
                        from_time: from_time, to_time: to_time,    
                        booked: 1, therapy_session: "", cost_center: "Rehab - TG"
                    });
                });

                if (hasError) return;

                const duplicates = checkForDuplicates(scheduleDataForDup);
                if (duplicates.length > 0) {
                    frappe.msgprint({ title: 'Duplicate Token', indicator: 'red', message: `Token clash detected! You assigned the same Token Number on the same Date.` });
                    return; 
                }
                
                frappe.dom.freeze(__('Creating Smart Automation Records & Invoice...'));

                // ==========================
                // CREATE SALES INVOICE
                // ==========================
                frappe.call({
                    method: "frappe.client.get",
                    args: { doctype: "Therapy Plan Template", name: frm.doc.therapy_plan_template },
                    callback: function (r) {
                        if (!r.message) return;

                        let linked_item = r.message.linked_item;
                        if (!linked_item) {
                            frappe.msgprint("Linked Item is missing in Therapy Plan Template.");
                            return;
                        }

                        frappe.call({
                            method: "frappe.client.get_list",
                            args: {
                                doctype: "Sales Invoice",
                                filters: { therapy_plan: frm.doc.name },
                                fields: ["name"], limit_page_length: 1
                            },
                            callback: function (si) {
                                if (si.message && si.message.length > 0) {
                                    frappe.msgprint({
                                        title: "Already Exists",
                                        message: "Sales Invoice is already created for this Therapy Plan.",
                                        indicator: "orange"
                                    });
                                    return;
                                }

                                frappe.call({
                                    method: "frappe.client.submit",
                                    args: {
                                        doc: {
                                            doctype: "Sales Invoice",
                                            naming_series: "ACC-SINV-.YYYY.-",
                                            customer: frm.doc.patient,
                                            type: "Therapy",
                                            therapy_plan: frm.doc.name,
                                            discount_percentage: frm.doc.discount_percentage || 0,
                                            cost_center: "Rehab - TG",
                                            posting_date: frm.doc.posting_date,
                                            set_posting_time: 1,
                                            items: [{
                                                item_code: linked_item, qty: 1, rate: frm.doc.itemamount,
                                                discount_percentage: frm.doc.discount_percentage || 0,
                                                cost_center: "Rehab - TG"
                                            }]
                                        }
                                    },
                                    callback: function (res) {
                                        if (res.message) {
                                            frappe.call({
                                                method: "frappe.client.set_value",
                                                args: {
                                                    doctype: frm.doctype, name: frm.doc.name,
                                                    fieldname: "sales_invoice", value: res.message.name
                                                },
                                                callback: function () {
                                                    frm.reload_doc();
                                                    frappe.msgprint({
                                                        title: "Sales Invoice Created",
                                                        message: `Invoice <b>${res.message.name}</b> has been created and linked successfully.`,
                                                        indicator: "green"
                                                    });
                                                }
                                            });
                                        }
                                    }
                                });
                            }
                        });
                    }
                });

                // ==========================================
                // CREATE AUTOMATION RECORDS & AUTO-COMPLETE
                // ==========================================
                const automation_promises = therapy_automation_data.map(doc => frappe.call({
                    method: 'frappe.client.insert',
                    args: { doc: Object.assign({ doctype: 'Therapy Automation' }, doc) }
                }));

                Promise.all(automation_promises).then(() => {
                    // --- AUTO UPDATE STATUS TO COMPLETED & LOCK BUTTON ---
                    frappe.model.set_value(cdt, cdn, 'status', 'Completed');
                    frappe.model.set_value(cdt, cdn, 'schedules', updated_schedule);
                    
                    // Button ko foran readonly kar do Grid ke andar
                    frm.fields_dict['therapy_plan_details'].grid.update_docfield_property(
                        'slot_assign', 'read_only', 1
                    );
                    
                    frappe.dom.unfreeze();
                    d.hide();
                    frm.refresh_field('therapy_plan_details');
                    
                    // Automatically Save form so the status persists in Database!
                    frm.save();
                    
                    frappe.show_alert({ 
                        message: `Successfully Scheduled ${updated_schedule.length} Tokens! Status marked as Completed & Locked.`, 
                        indicator: 'green' 
                    });
                }).catch(() => {
                    frappe.dom.unfreeze();
                    frappe.show_alert({message: "Failed to create Therapy Automation.", indicator: "red"});
                });
            }
        });

        d.show();

        setTimeout(() => {
            d.$wrapper.find('.sched-date').on('change', async function() {
                const $input = $(this);
                const $row = $input.closest('tr');
                const new_date = $input.val();
                
                if (!new_date) return;
                
                if (new_date < frm.doc.start_date || new_date > frm.doc.end_date) {
                    frappe.msgprint({title: 'Invalid Date', message: `You can only select dates between ${frm.doc.start_date} and ${frm.doc.end_date}.`, indicator: 'red'});
                    $input.val(''); 
                    $row.find('.sched-token, .sched-from-time, .sched-to-time').val('');
                    $row.find('.status-badge').html('❌ Invalid').removeClass('success warning default').addClass('danger');
                    return;
                }

                const d_obj = new Date(new_date + 'T00:00:00');
                const days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
                const new_day = days[d_obj.getDay()];
                
                $row.find('.day-badge').text(new_day).removeClass('monday tuesday wednesday thursday friday saturday sunday').addClass(new_day.toLowerCase());

                if (new_day.toLowerCase() === 'saturday' || new_day.toLowerCase() === 'sunday') {
                    $row.find('.sched-token').val('').css('border-color', '#f44336');
                    $row.find('.sched-from-time, .sched-to-time').val('');
                    $row.addClass('weekend-row');
                    $row.find('.status-badge').html('❌ Weekend').removeClass('success warning default').addClass('danger');
                    frappe.show_alert('Cannot schedule session on weekends!', 3);
                    return;
                }

                $row.removeClass('weekend-row');
                
                frappe.dom.freeze(__('Fetching available token for new date...'));
                try {
                    let booked_slots_response = await frappe.call({
                        method: 'frappe.client.get_list',
                        args: {
                            doctype: 'Therapy Automation',
                            filters: [
                                ['date', '=', new_date],
                                ['booked', '=', 1]
                            ],
                            or_filters: [
                                ['healthcare_practitioner', '=', row.healthcare_practitioner],
                                ['patient', '=', frm.doc.patient] // Patient overlap fix applied here
                            ],
                            fields: ['token_no']
                        }
                    }).then(r => r.message || []);

                    let local_ui_booked = [];
                    d.$wrapper.find('tbody tr').each(function() {
                        if ($(this).data('idx') !== $row.data('idx')) { 
                            let r_date = $(this).find('.sched-date').val();
                            let r_token = parseInt($(this).find('.sched-token').val());
                            if (r_date === new_date && !isNaN(r_token)) {
                                local_ui_booked.push(r_token);
                            }
                        }
                    });

                    let db_booked_tokens = booked_slots_response.map(b => parseInt(b.token_no)).filter(n => !isNaN(n));
                    let all_booked = [...db_booked_tokens, ...local_ui_booked];

                    let assigned_token = null;
                    for (let t = 1; t <= 13; t++) {
                        if (!all_booked.includes(t)) {
                            assigned_token = t;
                            break;
                        }
                    }

                    if (assigned_token) {
                        const mapped_times = tokenMap[assigned_token];
                        $row.find('.sched-token').val(assigned_token).css('border-color', '#4caf50');
                        $row.find('.sched-from-time').val(mapped_times.from.substring(0, 5));
                        $row.find('.sched-to-time').val(mapped_times.to.substring(0, 5));
                        $row.find('.status-badge').html('✅ Available').removeClass('danger warning default').addClass('success');
                    } else {
                        $row.find('.sched-token').val('').css('border-color', '#f44336');
                        $row.find('.sched-from-time, .sched-to-time').val('');
                        $row.find('.status-badge').html('⚠️ Full').removeClass('success warning default').addClass('danger');
                        frappe.show_alert('Max 13 Sessions Reached for this date! Please choose another date.', 3);
                    }

                    $row.find('.sched-token').trigger('input');
                } catch (err) {
                    frappe.show_alert('Error fetching token data', 3);
                } finally {
                    frappe.dom.unfreeze();
                }
            });

            d.$wrapper.find('.sched-token').on('input', function() {
                const $row = $(this).closest('tr');
                const token_val = parseInt($(this).val());
                
                if (token_val >= 1 && token_val <= 13) {
                    const mapped_times = tokenMap[token_val];
                    $row.find('.sched-from-time').val(mapped_times.from.substring(0, 5));
                    $row.find('.sched-to-time').val(mapped_times.to.substring(0, 5));
                    $(this).css('border-color', '#4caf50'); 
                    $row.find('.status-badge').html('✅ Selected').removeClass('danger warning default').addClass('success');
                } else {
                    $row.find('.sched-from-time').val('');
                    $row.find('.sched-to-time').val('');
                    $(this).css('border-color', '#f44336'); 
                    if(token_val > 13 || token_val < 1) {
                        frappe.show_alert('Token number must be strictly between 1 and 13!', 3);
                    }
                }

                d.$wrapper.find('.schedule-row').removeClass('duplicate-row');
                const scheduleData = [];
                d.$wrapper.find('tbody tr').each(function() {
                    const date = $(this).find('.sched-date').val();
                    const t_no = $(this).find('.sched-token').val();
                    if (date && t_no) scheduleData.push({ row: $(this).data('idx'), date: date, token_no: t_no });
                });
                const duplicates = checkForDuplicates(scheduleData);
                duplicates.forEach(dup => {
                    d.$wrapper.find(`tr[data-idx="${dup.firstRow-1}"]`).addClass('duplicate-row');
                    d.$wrapper.find(`tr[data-idx="${dup.secondRow-1}"]`).addClass('duplicate-row');
                });
            });
        }, 100);
    }
});

