frappe.ui.form.on('Therapy Plan', {
    discount_amount: function(frm) { if (frm.doc.discount_type == "Amount") calculate_discount_percentage(frm); },
    discount_percentage: function(frm) { if (frm.doc.discount_type == "Percent") calculate_discount_amount(frm); },
    itemamount: function(frm) {
        if (frm.doc.discount_type == "Amount") calculate_discount_percentage(frm);
        else if (frm.doc.discount_type == "Percent") calculate_discount_amount(frm);
    },
    discount_type: function(frm) {
        if (frm.doc.discount_type == "Amount") calculate_discount_percentage(frm);
        else if (frm.doc.discount_type == "Percent") calculate_discount_amount(frm);
    }
});

function calculate_discount_percentage(frm) {
    let amount = frm.doc.discount_amount || 0;
    let itemamount = frm.doc.itemamount || 0;
    if (itemamount > 0 && frm.doc.discount_type == "Amount") {
        frm.set_value('discount_percentage', (amount / itemamount) * 100);
    } else {
        frm.set_value('discount_percentage', 0);
    }
}

function calculate_discount_amount(frm) {
    let percentage = frm.doc.discount_percentage || 0;
    let itemamount = frm.doc.itemamount || 0;
    if (itemamount > 0 && frm.doc.discount_type == "Percent") {
        let percent = Math.round(((percentage * itemamount) / 100) * 100) / 100;
        frm.set_value('discount_amount', percent);
    } else {
        frm.set_value('discount_amount', 0);
    }
}

