frappe.ui.form.on('Therapy Session', {
    from_time: function(frm) {
        calculate_duration(frm);
    },
    to_time: function(frm) {
        calculate_duration(frm);
    },
    before_save: function(frm) {
        calculate_duration(frm);
    },
    validate: function(frm) {
        calculate_duration(frm);
    }
});

function calculate_duration(frm) {
    if (frm.doc.from_time && frm.doc.to_time) {
        // Convert time strings (HH:MM:SS) to minutes
        let [from_h, from_m, from_s] = frm.doc.from_time.split(':').map(Number);
        let [to_h, to_m, to_s] = frm.doc.to_time.split(':').map(Number);

        // Convert both times to total minutes
        let from_total = from_h * 60 + from_m + from_s / 60;
        let to_total = to_h * 60 + to_m + to_s / 60;

        let duration = to_total - from_total;

        if (duration < 0) {
            frappe.msgprint(__('To Time must be after From Time'));
            frm.set_value('duration', 0);
            return;
        }

        // Round to nearest whole minute and set value
        frm.set_value('duration', Math.round(duration));
    }
}

