// Therapy Session name -> true/false: whether a Progress Note exists for it
const progressNoteState = new Map();

function getProgressNoteButton(doc) {
    const has_note = progressNoteState.get(doc.name);
    let html = "";

    if (has_note === true) {
        html = `
            <button class="btn btn-secondary btn-xs" disabled title="Progress Note created">
                <i class="fa fa-check"></i>
            </button>
        `;
    } else if (has_note === false) {
        // No note yet, even if the session is already submitted
        html = `
            <button class="btn btn-primary btn-xs"
                onclick="openProgressNoteDialog(event,'${doc.name}')"
                title="Progress Notes">
                <i class="fa fa-file-text-o"></i>
            </button>
        `;
    }

    // Empty until loadProgressNoteState() knows whether a note exists
    return `<span class="ts-progress-note" data-session="${doc.name}">${html}</span>`;
}

function loadProgressNoteState(listview) {
    const sessions = (listview.data || []).map((doc) => doc.name);
    if (!sessions.length) return;

    frappe.call({
        method: "healthcare.healthcare.doctype.therapy_session.therapy_session.get_sessions_with_progress_note",
        args: { sessions },
        callback(r) {
            const with_note = new Set(r.message || []);
            sessions.forEach((name) => progressNoteState.set(name, with_note.has(name)));

            listview.$result.find(".ts-progress-note").each(function () {
                $(this).replaceWith(getProgressNoteButton({ name: $(this).attr("data-session") }));
            });
        },
    });
}

