                        description: __("Select patient diagnosis"),
                    },
                    {
                        fieldtype: "Data",
                        fieldname: "target",
                        label: __("Target"),
                        reqd: 1,
                    },
                    {
                        fieldtype: "Column Break"
                    },
                    {
                        fieldtype: "Date",
                        fieldname: "date",
                        label: __("Date"),
                        reqd: 1,
                        default: frappe.datetime.get_today(),
                    },
                    {
                        fieldtype: "Data",
                        fieldname: "user",
                        label: __("User"),
                        read_only: 1,
                        default: frappe.session.user, // <--- isay change karein
                    },
                    {
                        fieldtype: "Section Break" // Full width for Text Areas
                    },
                    {
                        fieldtype: "Small Text",
                        fieldname: "activities",
                        label: __("Activities"),
                        reqd: 1,
                    },
                    {
                        fieldtype: "Small Text",
                        fieldname: "behavior_observation",
                        label: __("Behaviour / Observation"),
                    },
                ],

                primary_action_label: __("Save"),
                primary_action(values) {

                    // Python backend ko "table_rows" chahiye list format me, 
                    // isiliye data ko usi structure me wrap kar dia gaya hai.
                    const rows = [{
                        date: values.date,
                        target: values.target,
                        activities: values.activities,
                        behavior_observation: values.behavior_observation,
                        user: frappe.session.user // <--- yahan bhi frappe.session.user (ya values.user) likhein
                    }];

                    // Ignore repeated taps while a save is in progress
                    if (d.saving) return;
                    d.saving = true;
                    d.get_primary_btn().prop("disabled", true);
                    let saved = false;

                    frappe.call({
                        method: "healthcare.healthcare.doctype.therapy_session.therapy_session.create_progress_note",
                        args: {
                            therapy_session: session_name,
                            patient_name: data.patient_name,
                            diagnosis: values.diagnosis,
                            age: data.age,
                            user: values.user,
                            table_rows: JSON.stringify(rows),
                        },
                        freeze: true,
                        freeze_message: __("Saving Progress Note..."),
                        callback(r) {
                            if (!r.message) return;
                            saved = true;
                            frappe.show_alert({
                                message: r.message.message || __("Progress note saved"),
                                indicator: "green",
                            });
                            d.hide();
                            progressNoteState.set(session_name, true);
                            // Refresh so the blue icon turns into the tick right away
                            if (window.cur_list && cur_list.doctype === "Therapy Session") {
                                cur_list.refresh();
                            }
                        },
                        always() {
                            // On error keep the dialog open so the user can fix and retry
                            if (!saved) {
                                d.saving = false;
                                d.get_primary_btn().prop("disabled", false);
                            }
                        },
                    });
                },
            });

            d.show();
        },
    });
};

