function create_invoice(frm) {
    frappe.call({
        method: 'healthcare.healthcare.doctype.patient_appointment.patient_appointment.create_sales_invoice_from_appointment',
        args: {
            appointment_name: frm.doc.name,
            patient: frm.doc.patient,
            appointment_type: frm.doc.appointment_type,
            cost_center: frm.doc.cost_center,
            discount_amount: flt(frm.doc.discount_amount),
            discount_percentage: flt(frm.doc.discount_percent)
        },
        callback: function(r) {
            if (r.message) {
                // Show success message
                frappe.show_alert({
                    message: __('Sales Invoice {0} created successfully', [r.message.name]),
                    indicator: 'green'
                }, 5);
                
                // Refresh the form - this will trigger refresh event and change button
                frm.reload_doc();
                
                // Optional: Show success dialog
                show_success_message(r.message.name);
            }
        },
        freeze: true,
        freeze_message: __('Creating Sales Invoice...')
    });
}

function show_success_message(invoice_name) {
    let dialog = new frappe.ui.Dialog({
        title: __('Success'),
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'message',
                options: `
                    <div style="text-align: center; padding: 20px;">
                        <i class="fa fa-check-circle text-success" style="font-size: 36px; margin-bottom: 15px;"></i>
                        <h4 style="margin-bottom: 10px;">Sales Invoice Created!</h4>
                        <p style="margin-bottom: 20px;">Invoice Number: <b>${invoice_name}</b></p>
                    </div>
                `
            }
        ],
        primary_action_label: __('View Invoice'),
        primary_action: function() {
            frappe.set_route('Form', 'Sales Invoice', invoice_name);
            dialog.hide();
        },
        secondary_action_label: __('Stay Here'),
        secondary_action: function() {
            dialog.hide();
        }
    });
    
    dialog.show();
}


frappe.ui.form.on("Patient Appointment", {
    discount_amount(frm) {
        calculate_discount(frm);
    },
    discount_type(frm) {
        calculate_discount(frm);
    },
    appointment_type(frm) {
        // Recalculate when appointment type changes
        calculate_discount(frm);
    }
});

function calculate_discount(frm) {
    if (frm.doc.discount_type === "Amount") {

        // Get Appointment Type Doc
        if (frm.doc.appointment_type) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Appointment Type",
                    name: frm.doc.appointment_type
                },
                callback: function(r) {
                    if (!r.message) return;

                    // Child table inside Appointment Type
                    let items = r.message.items;

                    if (items && items.length > 0) {
                        let charge = items[0].op_consulting_charge;  // Assuming first row

                        if (charge > 0 && frm.doc.discount_amount > 0) {
                            let percent = (frm.doc.discount_amount / charge) * 100;

                            frm.set_value("discount_percent", percent);
                        }
                    }
                }
            });
        }
    }
}
